using System.IO.Compression;
using System.Text;
using System.Xml.Linq;
using Chitalka.Core;
using Xunit;
namespace Chitalka.Tests;
public sealed class CoreTests : IDisposable
{
    readonly string root = Path.Combine(Path.GetTempPath(), "chitalka-test-" + Guid.NewGuid());
    const string Hash = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
    const string Locator = "{\"href\":\"OEBPS/chapter.xhtml\",\"locations\":{\"progression\":0.25},\"text\":{\"highlight\":\"curious\"}}";
    Word Word(string id="one",string translation="любопытный") => new(id,"curious","curious",translation,"She was curious.",Hash,"Book",Locator,"test",1);
    Store NewStore() => new(root);
    [Fact] public void StateSurvivesRestartAndFailedEditIsAtomic() { var s=NewStore();s.AddWord(Word()); Assert.Throws<InvalidOperationException>(()=>s.Change(x=>{x.Data.Words.Clear();throw new InvalidOperationException();}));Assert.Single(new Store(root).State.Data.Words); }
    [Fact] public void MeaningDedupDoesNotLoseData() { var s=NewStore();Assert.Equal("one",s.AddWord(Word()));Assert.Equal("one",s.AddWord(Word("two")));s.AddWord(Word("three","странный"));Assert.Equal(2,s.State.Data.Words.Count); }
    [Fact] public void PracticeAndHistoryResume() { var s=NewStore();s.AddWord(Word());s.BeginPractice();s.Rate(2);var restored=new Store(root);Assert.Equal(1,restored.State.Practice!.Good);Assert.Single(restored.State.Data.Reviews); }
    [Fact] public void DeleteBookRetainsLearning() { var s=NewStore();s.Change(x=>x.Library.Add(new(Hash,"Book","Author","book.opf",null,1)));s.AddWord(Word());s.DeleteBook(Hash);Assert.Empty(s.State.Library);Assert.Single(s.State.Data.Words); }
    [Fact] public void AndroidBackupRoundTripPreservesLocators() { var b=new Backup { Words=[Word()], Books=[new(Hash,"Book","Author",Locator,.25,1)],Bookmarks=[new("mark",Hash,"Book","Author",Locator,"curious","note",1,2)],Reviews=[new("one",2,3)] };var decoded=BackupCodec.Decode(BackupCodec.Encode(b));Assert.Equal(Locator,decoded.Bookmarks.Single().Locator);Assert.Equal(b.Words,decoded.Words);Assert.Equal("ru.chitalka.app.backup",decoded.Format); }
    [Theory][InlineData("{}")] [InlineData("{\"format\":\"bad\"}")] [InlineData("{broken")] public void InvalidBackupsRejected(string json) => Assert.ThrowsAny<Exception>(()=>BackupCodec.Decode(json));
    [Fact] public void InvalidReviewAndDuplicatesRejected() { var b=new Backup { Words=[Word(),Word()] };Assert.Throws<InvalidDataException>(()=>BackupCodec.Encode(b));b.Words=[Word()];b.Reviews=[new("missing",0,0)];Assert.Throws<InvalidDataException>(()=>BackupCodec.Encode(b)); }
    [Fact] public void BadHashProgressAndLocatorRejected() { var b=new Backup { Books=[new("bad","","",Locator,0,0)] };Assert.Throws<InvalidDataException>(()=>BackupCodec.Encode(b));b.Books=[new(Hash,"","",Locator,2,0)];Assert.Throws<InvalidDataException>(()=>BackupCodec.Encode(b));Assert.ThrowsAny<Exception>(()=>BackupCodec.CheckLocator("{\"href\":\"\"}")); }
    [Fact] public void RestoreMergesMeaningsAndRemapsHistory() { var s=NewStore();s.AddWord(Word());var b=new Backup { Words=[Word("incoming")],Reviews=[new("incoming",1,5)] };BackupCodec.Restore(s,BackupCodec.Encode(b));BackupCodec.Restore(s,BackupCodec.Encode(b));Assert.Single(s.State.Data.Words);Assert.Single(s.State.Data.Reviews);Assert.Equal("one",s.State.Data.Reviews.Single().WordId);Assert.Equal(2,Directory.GetFiles(Path.Combine(root,"backups")).Length); }
    [Fact] public void InvalidRestoreLeavesStoreUnchanged() { var s=NewStore();s.AddWord(Word());Assert.ThrowsAny<Exception>(()=>BackupCodec.Restore(s,"{}"));Assert.Single(new Store(root).State.Data.Words); }
    [Theory][InlineData("../escape")] [InlineData("a/../../escape")] [InlineData("C:/secret")] [InlineData("/root")] [InlineData("%2e%2e/escape")] public void PathTraversalRejected(string path) => Assert.Throws<InvalidDataException>(()=>EpubLibrary.SafePath(root,path));
    [Fact] public void CsvEscapesFormulaAndQuotes() { var b=new Backup { Words=[Word() with { Translation=" =HYPERLINK(\"bad\")" }] };Assert.Contains("' =HYPERLINK(\"\"bad\"\")",BackupCodec.Csv(b)); }
    [Fact] public void ActiveContentRemovedButTextRetained() { var xml=XDocument.Parse("<html xmlns='http://www.w3.org/1999/xhtml'><head><script>alert(1)</script></head><body onload='bad()'><p>Read me</p><iframe src='https://bad'/><a href='javascript:bad()'>link</a></body></html>");EpubLibrary.Sanitize(xml);Assert.DoesNotContain("alert",xml.ToString());Assert.DoesNotContain("onload",xml.ToString());Assert.DoesNotContain("javascript:",xml.ToString());Assert.Contains("Read me",xml.ToString());Assert.Contains("script-src 'none'",xml.ToString()); }
    [Fact] public async Task ImportAndReimportPreserveIdentity() { Directory.CreateDirectory(root);var path=Path.Combine(root,"test.epub");using(var z=ZipFile.Open(path,ZipArchiveMode.Create)){void Entry(string p,string content){using var w=new StreamWriter(z.CreateEntry(p).Open());w.Write(content);}Entry("META-INF/container.xml","<container><rootfiles><rootfile full-path='OEBPS/content.opf'/></rootfiles></container>");Entry("OEBPS/content.opf","<package><metadata><title>Test Book</title><creator>Writer</creator></metadata><manifest><item id='c' href='chapter.xhtml' media-type='application/xhtml+xml'/></manifest><spine><itemref idref='c'/></spine></package>");Entry("OEBPS/chapter.xhtml","<html xmlns='http://www.w3.org/1999/xhtml'><head/><body><p>curious</p><script>bad()</script></body></html>");}var store=NewStore();var library=new EpubLibrary(store);var book=await library.Import(path);Assert.Equal("Test Book",book.Title);Assert.Equal(book.Hash,(await library.Import(path)).Hash);Assert.Single(store.State.Library);store.DeleteBook(book.Hash);Assert.Equal(book.Hash,(await library.Import(path)).Hash);Assert.DoesNotContain("bad()",File.ReadAllText(Path.Combine(root,"books",book.Hash,"OEBPS/chapter.xhtml"))); }
    [Fact] public void InflectionCandidatesAreBoundedAndExplicit() { Assert.Contains("run",DictionaryService.Candidates("running"));Assert.Contains("child",DictionaryService.Candidates("children"));Assert.Contains("go",DictionaryService.Candidates("went"));Assert.Equal("can't",DictionaryService.Key("Can’t")); }
    [Fact] public async Task RealDictionaryWorksOfflineAndPreservesUserStore() { var store=NewStore();store.AddWord(Word());var d=new DictionaryService(Path.Combine(AppContext.BaseDirectory,"Dictionary"),root);Assert.NotEmpty(await d.Lookup("curious"));Assert.Contains(await d.Lookup("went"),x=>x.Headword=="go");Assert.Contains(await d.Lookup("children"),x=>x.Headword=="child");Assert.Contains(await d.Lookup("running"),x=>x.Headword=="run"||x.Headword=="running");Assert.Empty(await d.Lookup("zzzxqwonotaword"));Assert.Single(new Store(root).State.Data.Words); }
    public void Dispose(){Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();if(Directory.Exists(root))Directory.Delete(root,true);}
}
